# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# C-form system instructions (VLEPEM Rev. 0 Figure A-2, Table B-2).

# CHECK: se_illegal # encoding: [0x00,0x00]
se_illegal
# CHECK: se_isync # encoding: [0x00,0x01]
se_isync
# CHECK: se_sc # encoding: [0x00,0x02]
se_sc
# CHECK: se_rfi # encoding: [0x00,0x08]
se_rfi
# CHECK: se_rfci # encoding: [0x00,0x09]
se_rfci
# CHECK: se_rfdi # encoding: [0x00,0x0a]
se_rfdi
# CHECK: se_rfmci # encoding: [0x00,0x0b]
se_rfmci
